package com.bank.roster;

import java.util.*;
import java.util.logging.*;

public class InvertDemo {
    private static final Logger log = Logger.getLogger("Roster");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Map<String, List<String>> deptToNames = Map.of(
            "IT", List.of("Rajesh", "Amit"),
            "Sales", List.of("Priya", "Neha"));
        RosterService service = new RosterService();

        Map<String, String> nameToDept = service.invert(deptToNames);
        log.info(() -> "Priya works in: " + nameToDept.get("Priya"));
        log.info(() -> "inverted = " + nameToDept);
    }
}

// ─── Would be in service/RosterService.java ───
class RosterService {
    Map<String, String> invert(Map<String, List<String>> deptToNames) {
        return deptToNames.entrySet().stream()
            .flatMap(e -> e.getValue().stream()                 // expand names list
                .map(name -> Map.entry(name, e.getKey())))      // name → department pair
            .collect(java.util.stream.Collectors.toMap(
                Map.Entry::getKey, Map.Entry::getValue));       // key by name
    }
}
